import{g as e,ad as s,r,A as t}from"./chunks/framework.B8tHCIha.js";const m=JSON.parse('{"title":"Charts","description":"","frontmatter":{},"headers":[],"relativePath":"docs/charts/overview.md","filePath":"docs/charts/overview.md","lastUpdated":1785774438000}'),o={name:"docs/charts/overview.md"};function c(h,a,p,n,d,i){return s(),r("div",null,[...a[0]||(a[0]=[t(`<h1 id="charts" tabindex="-1">Charts <a class="header-anchor" href="#charts" aria-label="Permalink to “Charts”">​</a></h1><p>Seven chart components under the <code>frappe-ui/charts</code> subpath, drawn with <a href="https://echarts.apache.org" target="_blank" rel="noreferrer">echarts</a>. Props are flat and name the columns of your data — <code>x</code>, <code>y</code>, <code>series</code>, <code>category</code>, <code>value</code> — so a saved or serialized chart is one typed object spread with <code>v-bind=&quot;savedChart&quot;</code>.</p><div class="language-js"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes tokyo-night github-light s_2cy0ei" tabindex="0" dir="ltr"><code><span class="line"><span class="s_edvzsf">import</span><span class="s_13ahmt"> { </span><span class="s_4q1z3w">BarChart</span><span class="s_1jjt6x">,</span><span class="s_4q1z3w"> LineChart</span><span class="s_13ahmt"> }</span><span class="s_edvzsf"> from</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/charts</span><span class="s_w1p9wo">&#39;</span></span>
<span class="line"><span class="s_edvzsf">import</span><span class="s_w1p9wo"> &#39;</span><span class="s_2575z4">frappe-ui/charts-style.css</span><span class="s_w1p9wo">&#39;</span></span></code></pre></div><p>The stylesheet carries the <code>--chart-*</code> color tokens. See <a href="/pr-preview/pr-890/docs/foundations/colors/charts">Chart Colors</a> for the three ramps and how to rebrand them. <code>palette</code> picks a ramp by name — <code>categorical</code>, <code>sequential</code> or <code>diverging</code> — or takes an explicit list of colors.</p><p>Each component registers only the echarts modules it draws, so a page with one BarChart pays for bars and nothing else.</p><h2 id="data-shapes" tabindex="-1">Data shapes <a class="header-anchor" href="#data-shapes" aria-label="Permalink to “Data shapes”">​</a></h2><p>The axis charts read either shape of the same data. Wide data keeps one column per series, so <code>y</code> lists the columns to draw. Long data keeps one row per point, so <code>y</code> names the single value column and <code>series</code> names the column that splits the rows apart. Pick whichever shape your query already returns.</p><h2 id="the-charts" tabindex="-1">The charts <a class="header-anchor" href="#the-charts" aria-label="Permalink to “The charts”">​</a></h2><ul><li><a href="/pr-preview/pr-890/docs/charts/bar-chart">BarChart</a> — grouped, stacked and horizontal bars</li><li><a href="/pr-preview/pr-890/docs/charts/line-chart">LineChart</a> — trends, a second value axis, gaps</li><li><a href="/pr-preview/pr-890/docs/charts/area-chart">AreaChart</a> — the line family with a fill</li><li><a href="/pr-preview/pr-890/docs/charts/donut-chart">DonutChart</a> — share of a total</li><li><a href="/pr-preview/pr-890/docs/charts/funnel-chart">FunnelChart</a> — stage-to-stage drop-off</li><li><a href="/pr-preview/pr-890/docs/charts/heatmap-chart">HeatmapChart</a> — magnitude across two dimensions</li><li><a href="/pr-preview/pr-890/docs/charts/number-card">NumberCard</a> — one reading, with its change</li></ul><p>Every chart shares the same <a href="/pr-preview/pr-890/docs/charts/states">loading, error and empty states</a>, and they compose into a <a href="/pr-preview/pr-890/docs/charts/dashboard">dashboard</a> without extra chrome.</p>`,10)])])}const f=e(o,[["render",c]]);export{m as __pageData,f as default};
